-- Baseline of the pre-Moa PostgreSQL schema. Existing databases require an explicit baseline after schema review.
create table applications (applicant_id bigint not null, created_at timestamp(6) not null, id bigint generated by default as identity, post_id bigint not null, updated_at timestamp(6) not null, status varchar(255) not null check ((status in ('PENDING','ACCEPTED','REJECTED'))), primary key (id), unique (post_id, applicant_id));
create table comments (deleted boolean not null, created_at timestamp(6) not null, id bigint generated by default as identity, member_id bigint not null, post_id bigint not null, updated_at timestamp(6) not null, content varchar(500) not null, primary key (id));
create table drivers (deleted boolean not null, review_count integer not null, total_rating_sum integer not null, created_at timestamp(6) not null, driver_id bigint generated by default as identity, member_id bigint not null, updated_at timestamp(6) not null, version bigint, car_color varchar(20) check ((car_color in ('WHITE','BLACK','GRAY','SILVER','RED','BLUE','BROWN'))), car_number varchar(20) not null unique, car_model varchar(50) not null, primary key (driver_id));
create table members (deleted boolean not null, created_at timestamp(6) not null, id bigint generated by default as identity, updated_at timestamp(6) not null, nickname varchar(50) not null, password varchar(60) not null, email varchar(100) not null unique, primary key (id));
create table notifications (created_at timestamp(6) not null, notification_id bigint generated by default as identity, read_at timestamp(6), receiver_id bigint not null, reference_id bigint, message varchar(100) not null, type varchar(255) not null check ((type in ('APPLICATION_RECEIVED','APPLICATION_ACCEPTED','APPLICATION_REJECTED','RIDE_STARTED','RIDE_ENDED','POST_CANCELLED','DEPARTURE_APPROACHING'))), primary key (notification_id));
create table post_tags (post_id bigint not null, tag_id bigint not null);
create table posts (auto_accept boolean not null, current_passengers integer not null, deleted boolean not null, departure_lat float(53), departure_lng float(53), destination_lat float(53), destination_lng float(53), max_passengers integer not null, price integer, created_at timestamp(6) not null, departure_time timestamp(6) not null, id bigint generated by default as identity, member_id bigint not null, updated_at timestamp(6) not null, version bigint, departure_location varchar(100) not null, destination_location varchar(100) not null, title varchar(100) not null, description TEXT, status varchar(255) not null check ((status in ('OPEN','CLOSED','CANCELLED'))), primary key (id));
create table reviews (rating integer not null, created_at timestamp(6) not null, driver_id bigint not null, id bigint generated by default as identity, reviewer_id bigint not null, ride_id bigint not null, updated_at timestamp(6) not null, comment varchar(500), primary key (id), unique (ride_id, reviewer_id));
create table ride_locations (latitude float(53) not null, longitude float(53) not null, id bigint generated by default as identity, recorded_at timestamp(6) not null, ride_id bigint not null, primary key (id));
create table ride_passengers (application_id bigint not null, boarded_at timestamp(6), created_at timestamp(6) not null, dropped_off_at timestamp(6), id bigint generated by default as identity, passenger_id bigint not null, ride_id bigint not null, updated_at timestamp(6) not null, payment_status varchar(255) not null check ((payment_status in ('UNPAID','PAID','WAIVED'))), status varchar(255) not null check ((status in ('PENDING','BOARDED','DROPPED_OFF'))), primary key (id));
create table rides (completed_at timestamp(6), created_at timestamp(6) not null, driver_id bigint not null, id bigint generated by default as identity, post_id bigint not null, started_at timestamp(6), updated_at timestamp(6) not null, status varchar(255) not null check ((status in ('SCHEDULED','IN_PROGRESS','COMPLETED'))), primary key (id));
create table tags (created_at timestamp(6) not null, id bigint generated by default as identity, updated_at timestamp(6) not null, name varchar(50) not null unique, primary key (id));
create index idx_notification_receiver_id on notifications (receiver_id);
create index idx_notification_receiver_read on notifications (receiver_id, read_at);
create index idx_posts_status_departure_time on posts (status, departure_time);
create index idx_ride_locations_ride_id_recorded_at on ride_locations (ride_id, recorded_at desc);
alter table if exists post_tags add constraint FKm6cfovkyqvu5rlm6ahdx3eavj foreign key (tag_id) references tags;
alter table if exists post_tags add constraint FKkifam22p4s1nm3bkmp1igcn5w foreign key (post_id) references posts;
alter table if exists ride_passengers add constraint FK80n7xfrib29dv54tmyhxqtwsf foreign key (ride_id) references rides;
